    def is_stylish(ribbons):
        for i in range(len(ribbons)):
            for j in range(len(ribbons)):
                if i != j and ribbons[i] in ribbons[j]:
                    return False
        return True

    def find_max_stylish_set(ribbons):
        n = len(ribbons)
        dp = [1] * n
        prev = [-1] * n

        for i in range(n):
            for j in range(i):
                if ribbons[j] not in ribbons[i] and dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1
                    prev[i] = j

        max_length = max(dp)
        index = dp.index(max_length)
        result = []

        while index != -1:
            result.append(index)
            index = prev[index]

        return max_length, result[::-1]

    input = sys.stdin.read().splitlines()
    n = int(input[0])
    ribbons = input[1:]

    max_length, indices = find_max_stylish_set(ribbons)

    print(max_length)
    print(' '.join(map(lambda x: str(x + 1), indices)))

